CREATE TABLE IF NOT EXISTS usuarios (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(100) NOT NULL, apellido VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, password_hash TEXT NOT NULL, rol VARCHAR(20) NOT NULL DEFAULT 'client' CHECK (rol IN ('admin','client')), creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS usuarios_email_unico ON usuarios(LOWER(email));
CREATE TABLE IF NOT EXISTS productos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, titulo VARCHAR(150) NOT NULL, categoria VARCHAR(50) NOT NULL, descripcion TEXT, precio NUMERIC(12,2) NOT NULL CHECK(precio>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), imagen_url TEXT, activo BOOLEAN NOT NULL DEFAULT TRUE, creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS eventos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, titulo VARCHAR(200) NOT NULL, descripcion TEXT, tipo VARCHAR(50), inicio TIMESTAMPTZ NOT NULL, fin TIMESTAMPTZ, ubicacion TEXT, capacidad INTEGER CHECK(capacidad>0), precio NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(precio>=0), imagen_url TEXT, creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK(fin IS NULL OR fin>=inicio));
CREATE TABLE IF NOT EXISTS proveedores (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(150) NOT NULL, persona_contacto VARCHAR(150), telefono VARCHAR(30), email VARCHAR(254), categoria VARCHAR(100), direccion TEXT, creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pedidos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT REFERENCES usuarios(id), nombre_cliente VARCHAR(200) NOT NULL, email_cliente VARCHAR(254) NOT NULL, estado VARCHAR(30) NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','procesando','enviado','entregado','cancelado')), total NUMERIC(12,2) NOT NULL CHECK(total>=0), creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pedido_detalles (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, pedido_id BIGINT NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE, producto_id BIGINT REFERENCES productos(id), titulo_producto VARCHAR(150) NOT NULL, cantidad INTEGER NOT NULL CHECK(cantidad>0), precio_unitario NUMERIC(12,2) NOT NULL CHECK(precio_unitario>=0));
ALTER TABLE productos ADD COLUMN IF NOT EXISTS datos JSONB NOT NULL DEFAULT '{}';
ALTER TABLE eventos ADD COLUMN IF NOT EXISTS datos JSONB NOT NULL DEFAULT '{}';
ALTER TABLE eventos ADD COLUMN IF NOT EXISTS activo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS datos JSONB NOT NULL DEFAULT '{}';
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS direccion JSONB NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS sesiones (token_hash TEXT PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, vence_en TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS reservas (id UUID PRIMARY KEY, evento_id BIGINT NOT NULL REFERENCES eventos(id), usuario_id BIGINT NOT NULL REFERENCES usuarios(id), nombre TEXT NOT NULL, email TEXT NOT NULL, telefono TEXT, lugares INTEGER NOT NULL CHECK(lugares>0), total NUMERIC(12,2) NOT NULL CHECK(total>=0), creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS pedidos_usuario_idx ON pedidos(usuario_id);
CREATE INDEX IF NOT EXISTS detalles_pedido_idx ON pedido_detalles(pedido_id);
CREATE INDEX IF NOT EXISTS reservas_evento_idx ON reservas(evento_id);
